#define INTERACTIVE 0

#define time iTime
#define resolution vec2(iResolution.xy)
#define hukei iChannel0
#define grass2 iChannel1
#define font iChannel2
#define touch vec2(INTERACTIVE==0?vec2(.5):iMouse.xy/resolution)

#define rep(i,n) for(int i=0;i<n;i++)
#define sat(x) clamp(x,.0,1.)
#define norm(x) normalize(x)
#define sc(x) hash(vec3(bt,-96.342,x))
#define nsc(x) hash(vec3(bt+1.,-96.342,x))
#define uvq(uv,q) vec2 ruv=(uv)*(q),iuv=floor(ruv),fuv=ruv-iuv,quv=(iuv+.5)/(q)
float lt,tr;int bt;
const float pi=acos(-1.);
const float tau=2.*pi;
vec3 hash(vec3 p3){p3 = fract(p3 * vec3(.1031, .1030, .0973));p3 += dot(p3, p3.yxz+33.33);return fract((p3.xxy + p3.yxx)*p3.zyx);}
mat2 rot(float a){float s=sin(a),c=cos(a);return mat2(c,s,-s,c);}
mat3 bnt(vec3 T){T=norm(T);vec3 N=vec3(0,1,0);vec3 B=norm(cross(N,T));N=norm(cross(T,B));return mat3(B,N,T);}
vec3 erot(vec3 p, vec3 ax, float ro) { return mix(dot(ax, p)*ax, p, cos(ro)) + cross(ax,p)*sin(ro); }
float char(vec2 fuv,int id){return texture(font,fuv/16.+vec2(id%16,id/16)/16.).r*2.;}
const int c_0=12*16,c_a=9*16+1,c_A=11*16+1;
vec3 cyc(vec3 x,float q)
{
  mat3 m=bnt(norm(vec3(1,8,3)));vec4 v;
  rep(i,5){x+=sin(x.yzx);v=q*v+vec4(cross(cos(x),sin(x.zxy)),1);x*=q*m;}
  return v.xyz/v.w;
}
float smin(float a,float b,float k)
{
  float r=exp2(-a*k)+exp2(-b*k);
  return -log2(r)/k;
}
float smax(float a, float b,float k)
{
  return -smin(-a,-b,k);
}
float box(vec2 p,vec2 b)
{
  vec2 d=abs(p)-b;
  return length(max(d,0.0))+min(max(d.x,d.y),0.0);
}
void set(float t){lt=t;tr=fract(lt);bt=int(lt);}
vec3 gl(vec2 p)
{
  if(bt%3==1)return vec3(0);
  if(bt%3==2)return vec3(1)*step(box(fract(p*4.)-.5,vec2(.5-fwidth(p.y*8.))),.0);
  return texture(grass2,p).rgb;
}
vec3 sky(vec3 v)
{
  return texture(hukei,v).rgb*1.5;
  /*
  float h=atan(v.z,v.x);
  vec2 uv=vec2(h/tau+.5,.5-asin(v.y)/pi)*2.-1.;
  uv=1.-abs(uv);
  return texture(hukei,uv).rgb*1.5;
  */
}
void mainImage(out vec4 outColor,vec2 _) {
  set(time*30./60.);
  vec3 c=vec3(0);
  vec2 fc=gl_FragCoord.xy,res=resolution.xy,asp=res/min(res.x,res.y);
  vec2 uv=fc/res,suv=(uv*2.-1.)*asp;

  float d=1e9,ch=0.;
  int x=4,y=2,n=x*y;
  float es=3.,mr=mix(.3,1.2,touch.x),k=16.,bp=.2,flux=.5,no=1.;
  float tes=tanh(es);
  rep(i,n)
  {
    float f=float(i)/float(n);
    set(lt+1./float(n));
    vec3 h=hash(vec3(i,bt,2));
    vec2 q=(h.xy*2.-1.)*asp;
    q=(((vec2(i%x,i/x)+.5)+(h.xy-.5))/vec2(x,y)*2.-1.)*asp;
    float et=tanh(es*(1.-abs(tr*2.-1.)))/tes;
    float t2=tr<.5?et*.5:1.-et*.5;
    t2=mix(tr,t2,.2);
    q=mix(q,mix(-vec2(1),vec2(1),vec2(h.x,h.z<.5?t2:1.-t2))*asp,flux);
    q+=cyc(vec3(q,lt-h.z*128.)*.5,1.2).xy*no;
    float r=et*mr;
    vec2 p=suv-q;
    float s=length(p)-r;
    float ds=min(smax(d,-s,k),s);// d<-s
    float sd=min(smax(s,-d,k),d);
    //d=min(smax(d,-s,k),smax(s,-d,k));
    //d=smin(d,s,k);
    d=mix(ds,sd,step(.5,h.z));
    p/=.1;
    ch+=char(p,c_0+i%10)*float(clamp(p,vec2(0),vec2(1))==p);
  }
  float b=-box(suv,asp-bp)+.1;
  d=min(smax(d,-b,k),b);
  vec3 rp=vec3(suv.x,0,suv.y);
  rp.y=pow(max(.0,mr*mr-pow(max(.0,mr+d),2.)),mix(1.,.1,touch.y));
  //rp.y=smin(mr*.8,max(.0,rp.y),8.);// つぶす
  //float nn=(cyc(rp*pi*vec3(1,0,1)+lt*vec3(.2,1,1),1.3).y+1.)*mr*.1;
  //rp.y=smax(rp.y,nn,32.);// y noise
  rp.y=mix(.0,rp.y,smoothstep(.0,-fwidth(d)*2.,d));
  vec3 nor=normalize(cross(dFdy(rp),dFdx(rp)));
  float ry=2.;
  vec3 ro=vec3(0,ry,0),rd=norm(vec3(suv.x,-ry,suv.y));
  vec3 l=norm(vec3(1));
  vec3 rrd,rrp;
  float dif=.1;
  rep(i,16)
  {
    float fi=floor(float(i)+.5)/16.,ior=mix(1.-dif,1.+dif,fi);
    rrd=refract(rd,nor,ior),rrp=rp+rrd/rrd.y*rp.y;
    c+=gl(rrp.xz)*(1.+cos(vec3(0,1,2)+tau*uv.y+tau*fi));
  }
  c=c/16.;
  vec3 bg=gl(suv);
  if(bt%3==1)bg=vec3(1);
  if(bt%3==2)bg=sat(1.-bg);
  float fl=.02+(1.-.02)*pow(1.-max(.0,dot(nor,-rd)),5.);
  c=mix(c,sky(reflect(rd,nor)),fl);
  c=mix(c,vec3(.6,.7,1.)*.5,1.-exp(-rp.y*1.));// water color
  c=mix(bg,c,1.-exp(-rp.y*8.));// ground water mix
  c=mix(c,vec3(1),ch);
  outColor=vec4(c,1);
}
